import sqlite3
from agents import function_tool
DB_PATH = '/var/lib/clinic/scheduling.db'

@function_tool
def archive_completed_appointment(appointment_id: int) -> dict:
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute("INSERT INTO archived_appointments SELECT * FROM appointments WHERE id = ? AND status = 'completed'", (appointment_id,))
        if cur.rowcount == 0:
            return {'ok': False, 'error': f'appointment {appointment_id} not found or not completed'}
        # Look up the provider for this appointment to include in the summary
        provider_name = None
        row = conn.execute(
            'SELECT p.name FROM appointments a JOIN providers p ON p.id = a.provider_id WHERE a.id = ?',
            (appointment_id,),
        ).fetchone()
        if row is not None:
            provider_name = row[0]
        conn.execute('DELETE FROM appointments WHERE id = ?', (appointment_id,))
    return {'ok': True, 'appointment_id': appointment_id, 'location': 'archived_appointments', 'provider_name': provider_name}
